# D0 (2P) path
process.d0Path = cms.Path(
    process.unpackedTracksAndVertices +
    process.d0Candidates +
    process.d0Tree
)

# D0 (2P) wrong sign path
process.d0PathWS = cms.Path(
    process.unpackedTracksAndVertices +
    process.d0CandidatesWS +
    process.d0TreeWS
)

