process.d04pPath = cms.Path(
    process.unpackedTracksAndVertices +
    process.d04pCandidates +
    process.d04pTree
)

# D* (3P) path - depends on D0
process.dStarPath = cms.Path(
    process.unpackedTracksAndVertices +
    process.d0Candidates +
    process.d0Tree +
    process.dStarCandidates +
    process.dStarTree
)

# D* (3P) wrong sign path
